<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_officer');$user=current_user();$flashes=render_flashes();$currentPage='reports';$pageTitle='Programme Reports';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$officerId=(int)($user['id']??$user['user_id']??0);if($officerId<=0){http_response_code(403);exit('Invalid Programme Officer account.');}$scope=po_scope($conn,'p','c');$rows=[];if($scope['mode']!=='none'){$sql="SELECT p.id,p.name,p.type,p.status,COUNT(DISTINCT c.id) cohorts,COUNT(DISTINCT CASE WHEN cp.status<>'withdrawn' THEN cp.user_id END) candidates,COUNT(DISTINCT CASE WHEN cp.status='active' THEN cp.user_id END) active_candidates,COUNT(DISTINCT CASE WHEN cp.status='completed' THEN cp.user_id END) completed_candidates,COUNT(DISTINCT CASE WHEN cp.status='withdrawn' THEN cp.user_id END) withdrawn_candidates FROM programmes p LEFT JOIN cohorts c ON c.programme_id=p.id LEFT JOIN cohort_participants cp ON cp.cohort_id=c.id WHERE {$scope['condition']} GROUP BY p.id,p.name,p.type,p.status ORDER BY p.name";$stmt=$conn->prepare($sql);$stmt->bind_param('i',$officerId);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc()){$row['completion_rate']=po_completion_rate((int)$row['candidates'],(int)$row['completed_candidates']);$rows[]=$row;}$stmt->close();}$tp=count($rows);$tc=array_sum(array_column($rows,'cohorts'));$tn=array_sum(array_column($rows,'candidates'));$td=array_sum(array_column($rows,'completed_candidates'));$rate=po_completion_rate($tn,$td);require __DIR__.'/_layout_start.php';?>
<div class="po-page-header"><div><span class="po-page-header__eyebrow">Insights & Reporting</span><h2>Programme Reports</h2><p>Portfolio-level delivery, participation and completion indicators for programmes available to your workspace.</p></div></div>
<section class="po-stats po-stats--4"><article class="po-stat"><span class="po-stat__icon po-stat__icon--blue"><i class="fas fa-diagram-project"></i></span><strong><?= number_format($tp) ?></strong><span>Programmes</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--purple"><i class="fas fa-layer-group"></i></span><strong><?= number_format($tc) ?></strong><span>Cohorts</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--orange"><i class="fas fa-users"></i></span><strong><?= number_format($tn) ?></strong><span>Candidates</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--green"><i class="fas fa-chart-line"></i></span><strong><?= $rate ?>%</strong><span>Completion Rate</span></article></section>
<div class="po-card"><div class="po-card__header"><div><h3>Programme Performance</h3><p>Consolidated programme delivery metrics.</p></div></div><?php if(!$rows):?><div class="po-empty"><div class="po-empty__icon"><i class="fas fa-chart-column"></i></div><strong>No report data</strong><span>Programme metrics will appear once assignments and participants are available.</span></div><?php else:?><div class="po-table-wrap"><table class="po-table"><thead><tr><th>Programme</th><th>Status</th><th>Cohorts</th><th>Candidates</th><th>Active</th><th>Completed</th><th>Withdrawn</th><th>Completion</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['name']) ?></strong><span class="po-table-sub"><?= e((string)($r['type']??'Programme')) ?></span></td><td><span class="po-status po-status--<?= e(po_status_class($r['status'])) ?>"><?= e(po_status_label($r['status'])) ?></span></td><td><?= number_format((int)$r['cohorts']) ?></td><td><?= number_format((int)$r['candidates']) ?></td><td><?= number_format((int)$r['active_candidates']) ?></td><td><?= number_format((int)$r['completed_candidates']) ?></td><td><?= number_format((int)$r['withdrawn_candidates']) ?></td><td><div class="po-progress po-progress--table"><div class="po-progress__labels"><span>Progress</span><strong><?= (int)$r['completion_rate'] ?>%</strong></div><div class="po-progress__track"><span style="width:<?= (int)$r['completion_rate'] ?>%"></span></div></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>
